    cluster.writeAttributeWrongCodeEntryLimit(withValue: MTRMakeDataValue(type: MTRUnsignedIntegerValueType, value: n(1)), expectedValueInterval: n(1), params: MTRWriteParams())
    let probe = MTRMakeDataValue(type: MTRUnsignedIntegerValueType, value: n(7))
    cluster.writeAttributeAutoRelockTime(withValue: probe, expectedValueInterval: n(1))
    let cached = cluster.readAttributeAutoRelockTime(with: nil)
    mtrRequire(cached != nil, "expected-value cache round-trip")
